let data = msg.payload.messages || [];

let filtered = data.filter(
    entry => new Date(entry.createdAt).getTime() > global.get("last_wasos_timestamp") || 0
);

msg.payload = filtered;
return msg;

let data = msg.payload;

let filtered = data.filter(entry => {
    // Remove rayvn-entries (duplicate protection)
    if (entry.username.includes("[rayvn]")) return false;

    // Remove parat-bridge system messages (loop-protection)
    if (entry.username.includes("[parat-bridge]")) return false;
    if (entry.content && entry.content.startsWith("[parat-bridge]")) return false;

    return true;
});

msg.payload = filtered;
return msg;

if (msg.payload && msg.payload.length > 0) {
    msg.topic = "new_messages"
    return msg;
}
else {
    return null;
}
